"""Illustrative composition geometry and source boundaries, not combat outcomes."""
import subprocess, unittest
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PRE="const assert=require('node:assert/strict'),E=require('./web_r4/loading-engine.js'),c=require('./web_r4/loading-data.json');const run=x=>E.analyze(x||E.exampleInput(c,0),c);"
class FormationTests(unittest.TestCase):
 def node(self,body):
  r=subprocess.run(['node','-e',PRE+body],cwd=ROOT,capture_output=True,text=True)
  self.assertEqual(r.returncode,0,r.stderr[-4500:])
 def test_actual_ten_picks_two_different_geometries_not_live_positions(self):
  self.node("const r=run(),f=r.coach.planboard.fight.formations;assert(f,'missing shared formation result');assert(f.supported);assert.equal(f.origin,'ILLUSTRATIVE_HYPOTHESIS');assert.equal(f.actual_enemy_positions,null);assert.deepEqual(f.scenes.map(s=>s.id),['FRONT_CONNECTED','FLANK_ISOLATE']);for(const s of f.scenes){assert.equal(s.actors.length,10);assert.equal(new Set(s.actors.map(a=>a.team+':'+a.champion)).size,10);assert.equal(s.steps.length,3);assert(s.conditions.length&&s.failure.length);assert.equal(s.winner,'UNDETERMINED');assert(s.basis==='DESIGN_HYPOTHESIS');assert(s.actors.every(a=>a.positions.length===3));}const [a,b]=f.scenes;assert.notDeepEqual(a.actors.map(a=>a.positions),b.actors.map(a=>a.positions));assert(a.favored_champion==='Caitlyn');assert(b.favored_champion==='Kaisa');assert(b.conditions.join(' ').includes('후속'));assert(b.failure.join(' ').includes('분리'));assert(f.evidence.official.length);assert(f.evidence.sources.every(s=>s.url&&s.excerpts.length));")
 def test_permutation_preference_and_own_highlight_do_not_rewrite_geometry(self):
  self.node("const x=E.exampleInput(c,0),a=run(x).coach.planboard.fight.formations;x.allies.reverse();x.enemies.reverse();assert.deepEqual(run(x).coach.planboard.fight.formations,a);for(const risk of ['LOSS_LIMIT','OPPORTUNITY']){x.schema_version='lol-coach-loading-input-v3';x.preferences={risk};x.scenario={standard:'lane-standard-v1',overrides:{}};assert.deepEqual(run(x).coach.planboard.fight.formations,a);}const y=E.exampleInput(c,0);[y.allies,y.enemies]=[y.enemies,y.allies];y.own_champion='Kaisa';y.own_position='BOTTOM';const f=run(y).coach.planboard.fight.formations;assert.equal(f.default_scene,'FLANK_ISOLATE');assert(f.scenes.every(s=>s.actors.find(a=>a.self).champion==='Kaisa'));assert.equal(f.scenes[0].favored_team,'ENEMY');")
 def test_missing_carry_frontline_and_patch_are_not_generic_supported_diagrams(self):
  self.node("let x=E.exampleInput(c,1);assert.equal(run(x).coach.planboard.fight.formations.supported,false);x=E.exampleInput(c,0);x.enemies.find(p=>p.champion==='Kaisa').champion='Jinx';assert.equal(run(x).coach.planboard.fight.formations.supported,false);x=E.exampleInput(c,0);x.allies.find(p=>p.champion==='Ornn').champion='Teemo';x.allies.find(p=>p.champion==='Sejuani').champion='Kindred';assert.equal(run(x).coach.planboard.fight.formations.supported,false);x=E.exampleInput(c,0);x.patch='1.1';assert.equal(run(x).coach.planboard.fight.formations.supported,false);")
 def test_unclassified_replacement_not_silently_given_flank_role(self):
  self.node("const x=E.exampleInput(c,0);x.enemies.find(p=>p.position==='MID').champion='Sona';const f=run(x).coach.planboard.fight.formations;assert(f.supported);const a=f.scenes[1].actors.find(a=>a.champion==='Sona');assert.notEqual(a.role,'측면 진입 후보');assert(f.scenes[1].failure.join(' ').includes('보호'));assert.equal(run().coach.planboard.fight.kill,'UNDETERMINED');")
 def test_protection_dependency_and_archived_tooltip_source_are_real(self):
  self.node("const fs=require('node:fs'),crypto=require('node:crypto'),f=run().coach.planboard.fight.formations;const fact=f.evidence.official.find(v=>v.locator.endsWith('tooltip'));const raw=fs.readFileSync(fact.local_source);assert.equal(crypto.createHash('sha256').update(raw).digest('hex'),fact.sha256);assert(JSON.parse(raw).data.Kaisa.spells[3].tooltip.includes(fact.raw_excerpt));const x=E.exampleInput(c,0);x.allies.find(p=>p.champion==='Lux').champion='Brand';assert.equal(run(x).coach.planboard.fight.formations.supported,false);")
 def test_frontline_fighters_do_not_overrun_flank_slots_or_destroy_report(self):
  self.node("const x=E.exampleInput(c,0);['Sett','LeeSin','Yasuo','Kaisa','Pantheon'].forEach((id,i)=>x.enemies[i].champion=id);const r=run(x);assert(r.summary&&r.coach.planboard);const f=r.coach.planboard.fight.formations;assert(f.supported);assert.equal(f.scenes[1].actors.length,10);const sett=f.scenes[1].actors.find(a=>a.champion==='Sett');assert.equal(sett.role,'전방 연결 후보');")
 def test_basic_attack_radii_and_cohesion_are_explicit_geometry_not_combat_verdicts(self):
  self.node("const f=run().coach.planboard.fight.formations;assert(f.range_reference,'missing official base-range references');assert.equal(f.range_reference.champions.Caitlyn.base_attack_range,650);assert.equal(f.range_reference.champions.Kaisa.base_attack_range,525);assert.equal(f.range_reference.board_width_game_units,2000);assert.equal(f.range_reference.origin,'ILLUSTRATIVE_SCALE');for(const s of f.scenes){assert.equal(s.cohesion.length,3);for(const v of s.cohesion){assert(v.links.length);assert.equal(v.nearest.length,10);assert(v.nearest.every(n=>n.distance_game_units>=0&&n.origin==='ILLUSTRATIVE_GEOMETRY'));assert.equal(v.tactical_isolation,'NOT_INFERRED');}}const flank=f.scenes[1],kai=flank.actors.find(a=>a.champion==='Kaisa'),cait=flank.actors.find(a=>a.champion==='Caitlyn');const d=Math.hypot(kai.positions[1].x-cait.positions[1].x,kai.positions[1].y-cait.positions[1].y)*20;assert(d<525,'chosen attack example should visually reach target under disclosed centre geometry');assert.equal(f.scenes[1].winner,'UNDETERMINED');")
 def test_relocated_front_does_not_overlap_non_flanking_backline(self):
  self.node("const x=E.exampleInput(c,0);['Malphite','Ivern','Ziggs','Kaisa','Janna'].forEach((id,i)=>x.enemies[i].champion=id);const f=run(x).coach.planboard.fight.formations;assert(f.supported);const a=f.scenes[1].actors;for(let i=0;i<a.length;i++)for(let j=i+1;j<a.length;j++){const p=a[i].positions[1],q=a[j].positions[1];assert(Math.hypot(p.x-q.x,p.y-q.y)>=16,a[i].champion+' overlaps '+a[j].champion);}")
if __name__=='__main__':unittest.main()
